import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { FIXTURE_DIR, ROOT } from './paths.ts';

/** Fixtures are generated by the same code the headless suites use (SPEC §15, no binary fixtures in git). */
export default function globalSetup(): void {
  if (existsSync(`${FIXTURE_DIR}/photo-1.jpg`) && !process.env.FOLIO_REBUILD_FIXTURES) return;
  execFileSync('pnpm', ['-s', 'cli', 'fixtures', '--out', FIXTURE_DIR], { cwd: ROOT, stdio: 'inherit' });
}
